		imgLocation = imgLocation.replaceAll(".png", "_edit.png");

		ImageButton editButton = new ImageButton(0, 0, 16, 16, 0, 0, 16, new ResourceLocation(imgLocation), 16, 32, e -> {
			int btnIndex = scrollList.getIndex(e);
