package net.hawthorn.dndsheets;

import com.google.gson.JsonObject;

import java.util.ArrayList;
import java.util.List;

/**
 * <p>What the character sheet screen shows for class resources (Rage, ki, Wild Shape...): which pools this character
 * has, how many uses they have and how many are left. A read-only view over the same sheet fields the managers write
 * ({@link RestResource}), public because {@code CharacterRules} and {@code RestResource} are package-private on purpose and the
 * screen lives in the client package. It computes nothing the rules don't already compute: it asks them.</p>
 */
public final class ResourceView {

	/** @param icon key under {@code textures/gui/icons/resource/}; @param nameKey translation key; @param max {@code -1} = unlimited. */
	public record Pool(String icon, String nameKey, int left, int max) {}

	private ResourceView() {
	}

	/** The pools that apply to this sheet's class(es), in a stable order. Empty for a class with none. */
	public static List<Pool> poolsFor(JsonObject sheet) {
		List<Pool> pools = new ArrayList<>();
		if (sheet == null) return pools;

		int barbarian = CharacterRules.classLevelOf(sheet, "barbarian", "bárbaro");
		if (barbarian > 0) {
			int max = CharacterRules.rageUsesFor(barbarian);
			boolean unlimited = max == Integer.MAX_VALUE;
			pools.add(new Pool("rage", "gui.dndsheets.sheet.res_rage",
				unlimited ? -1 : RestResource.usesLeft(sheet, RestResource.RAGE_USES, max), unlimited ? -1 : max));
		}
		int monk = CharacterRules.classLevelOf(sheet, "monk", "monje");
		if (CharacterRules.kiPointsFor(monk) > 0) {
			int max = CharacterRules.kiPointsFor(monk);
			pools.add(new Pool("ki", "gui.dndsheets.sheet.res_ki", RestResource.usesLeft(sheet, RestResource.KI_USES, max), max));
		}
		int sorcerer = CharacterRules.classLevelOf(sheet, "sorcerer", "hechicero");
		if (CharacterRules.sorceryPointsFor(sorcerer) > 0) {
			int max = CharacterRules.sorceryPointsFor(sorcerer);
			pools.add(new Pool("sorcery", "gui.dndsheets.sheet.res_sorcery", RestResource.usesLeft(sheet, RestResource.SORCERY_POINTS, max), max));
		}
		if (CharacterRules.classLevelOf(sheet, "druid", "druida") > 0) {
			pools.add(new Pool("wild_shape", "gui.dndsheets.sheet.res_wild_shape", RestResource.usesLeft(sheet, RestResource.WILD_SHAPE_USES, 2), 2));
		}
		if (CharacterRules.classLevelOf(sheet, "bard", "bardo") > 0) {
			int max = CharacterRules.bardicInspirationUsesFor(sheet);
			pools.add(new Pool("inspiration", "gui.dndsheets.sheet.res_inspiration", RestResource.usesLeft(sheet, RestResource.INSPIRATION_USES, max), max));
		}
		int fighter = CharacterRules.classLevelOf(sheet, "fighter", "guerrero");
		if (fighter > 0) {
			pools.add(new Pool("second_wind", "gui.dndsheets.sheet.res_second_wind", RestResource.isSpent(sheet, RestResource.SECOND_WIND) ? 0 : 1, 1));
			if (fighter >= 2) {
				pools.add(new Pool("surge", "gui.dndsheets.sheet.res_action_surge", RestResource.isSpent(sheet, RestResource.ACTION_SURGE) ? 0 : 1, 1));
			}
		}
		if (CharacterRules.classLevelOf(sheet, "cleric", "clérigo") > 0 || CharacterRules.classLevelOf(sheet, "cleric", "clerigo") > 0) {
			pools.add(new Pool("turn_undead", "gui.dndsheets.sheet.res_channel_divinity", RestResource.isSpent(sheet, RestResource.CHANNEL_DIVINITY) ? 0 : 1, 1));
		}
		return pools;
	}
}

package net.hawthorn.dndsheets.client.gui.components;

import net.hawthorn.dndsheets.client.gui.Icons;
import net.minecraft.client.gui.GuiGraphics;
import net.minecraft.client.gui.components.Button;
import net.minecraft.client.gui.components.Tooltip;
import net.minecraft.network.chat.Component;
import net.minecraft.resources.ResourceLocation;

/**
 * <p>A square tome-style button that holds only a glyph (a d20, a pencil, a plus), with its meaning in the tooltip. The
 * same parchment strip and bevel as {@link TomeButton}, so a row of small buttons next to a row of text ones reads as one
 * interface. Used where a text label would not fit, such as the roll buttons on the character sheet.</p>
 */
public class IconButton extends Button {
	private static final int FILL_IDLE = 0xF2241C13;
	private static final int FILL_HOVER = 0xF2382B1B;
	private static final int BEVEL_LIGHT = 0xFF5A4830;
	private static final int BEVEL_DARK = 0xFF0B0906;
	private static final int RAIL_HOVER = 0xFFC9A227;

	private final ResourceLocation icon;

	public IconButton(int x, int y, int size, ResourceLocation icon, Component tooltip, OnPress onPress) {
		super(x, y, size, size, Component.empty(), onPress, DEFAULT_NARRATION);
		this.icon = icon;
		this.setTooltip(Tooltip.create(tooltip));
	}

	@Override
	public void renderWidget(GuiGraphics guiGraphics, int mouseX, int mouseY, float partialTick) {
		int left = this.getX();
		int top = this.getY();
		int right = left + this.width;
		int bottom = top + this.height;
		boolean hot = this.isHoveredOrFocused() && this.active;

		guiGraphics.fill(left, top, right, bottom, hot ? FILL_HOVER : FILL_IDLE);
		guiGraphics.fill(left, top, right - 1, top + 1, hot ? RAIL_HOVER : BEVEL_LIGHT);
		guiGraphics.fill(left, top, left + 1, bottom - 1, hot ? RAIL_HOVER : BEVEL_LIGHT);
		guiGraphics.fill(left + 1, bottom - 1, right, bottom, BEVEL_DARK);
		guiGraphics.fill(right - 1, top + 1, right, bottom, BEVEL_DARK);

		int inset = Math.max(1, this.width / 8);
		Icons.draw(guiGraphics, icon, left + inset, top + inset, this.width - 2 * inset);
	}
}

