	private static void checkModBusSubscribersNameTheirMod() throws Exception {
		int checked = 0;
		for (String root : new String[]{"src/main/java", "dungeon/src/main/java", "species/src/main/java"}) {
			Path dir = Path.of(root);
			if (!Files.exists(dir)) continue;
			try (Stream<Path> walk = Files.walk(dir)) {
