import os, re

ROOT = r'C:\Users\DanCastello\Documents\GitHub\dndsheets'
MODULES = [
    ('src/main/java', 'net.hawthorn.dndsheets.DndsheetsMod.MODID'),
    ('dungeon/src/main/java', 'net.hawthorn.dndsheets.dungeon.DndsheetsDungeonMod.MODID'),
    ('species/src/main/java', 'net.hawthorn.dndsheets.species.DndsheetsSpeciesMod.MODID'),
]
PATTERN = re.compile(r'@((?:net\.minecraftforge\.fml\.common\.)?Mod\.EventBusSubscriber)(\(([^)]*)\))?')

changed = 0
for sub, const in MODULES:
    base = os.path.join(ROOT, sub.replace('/', os.sep))
    for dirpath, _, files in os.walk(base):
        for name in files:
            if not name.endswith('.java'):
                continue
            path = os.path.join(dirpath, name)
            text = open(path, encoding='utf-8', newline='').read()
            if 'EventBusSubscriber' not in text:
                continue

            def fix(m):
                args = m.group(3)
                # Only real annotations: skip matches inside comments (// ...) by checking the line start.
                line_start = text.rfind('\n', 0, m.start()) + 1
                if text[line_start:m.start()].strip().startswith('//') or text[line_start:m.start()].strip().startswith('*'):
                    return m.group(0)
                if args is not None and 'modid' in args:
                    return m.group(0)
                if args is None or not args.strip():
                    return '@%s(modid = %s)' % (m.group(1), const)
                if not re.match(r'\s*\w+\s*=', args):
                    args = 'value = ' + args.strip()
                return '@%s(modid = %s, %s)' % (m.group(1), const, args.strip())

            new = PATTERN.sub(fix, text)
            if new != text:
                open(path, 'w', encoding='utf-8', newline='').write(new)
                changed += 1
print('files changed:', changed)

