s=open(p,encoding='utf-8',newline='').read()
crlf='\r\n' in s; s=s.replace('\r\n','\n')
a=s.index("	//The jar holds three mods. A @Mod.EventBusSubscriber without modid")
b=s.index("	//Windows defaults to windows-1252.")
new='''	//The jar holds three mods. A @Mod.EventBusSubscriber without modid is registered for EVERY mod in the jar, so its handlers run
	//three times per event: on the MOD bus the screens registered three times and the client crashed ("Duplicate registration
	//for dndsheets:advanced_roll_editor"); on the FORGE bus one sword swing ran the combat handler three times, the first
	//spending the action and the other two answering "You already used your action this turn", and the server started the
	//content preload three times. Every subscriber has to name its mod.
	private static void checkModBusSubscribersNameTheirMod() throws Exception {
		int checked = 0;
		for (String root : new String[]{"src/main/java", "dungeon/src/main/java", "species/src/main/java"}) {
			Path dir = Path.of(root);
			if (!Files.exists(dir)) continue;
			try (Stream<Path> walk = Files.walk(dir)) {
				for (Path file : walk.filter(f -> f.toString().endsWith(".java")).toList()) {
					for (String line : Files.readAllLines(file)) {
						String trimmed = line.trim();
						if (trimmed.startsWith("//") || trimmed.startsWith("*") || trimmed.startsWith("/*")) continue;
						if (trimmed.startsWith("@") && trimmed.contains("Mod.EventBusSubscriber")) {
							checked++;
							assertTrue(trimmed.contains("modid"), file + " has an @Mod.EventBusSubscriber without modid: with three mods in one jar its handlers would run three times. Add modid = ...MODID.");
						}
					}
				}
			}
		}
		System.out.println("checkModBusSubscribersNameTheirMod: OK, " + checked + " event subscriber(s), each naming its mod.");
	}

'''
s=s[:a]+new+s[b:]
if crlf: s=s.replace('\n','\r\n')
open(p,'w',encoding='utf-8',newline='').write(s)
